const getMaxTriples = (n) => {
  const countResidue = (r) => {
    // a[i] = i*i - i + 1 = i*(i-1) + 1
    // a[i] % 3 === 0 when i % 3 === 2
    // a[i] % 3 === 1 when i % 3 === 0 or 1
    // residues are only 0 or 1, so a[i]+a[j]+a[k] % 3 === 0
    // requires all three residues 0, or all three residues 1
    const c0 = Math.floor((n + 1) / 3);
    return r === 0 ? c0 : n - c0;
  };

  const comb3 = (x) => (x >= 3 ? (x * (x - 1) * (x - 2)) / 6 : 0);

  return comb3(countResidue(0)) + comb3(countResidue(1));
};

